44	        this.windows = windows;
45	        this.emitStrategy = emitStrategy;
46	
47	        retentionPeriod = retentionPeriod();
48	
49	        if ((windows.size() + windows.gracePeriodMs()) > retentionPeriod) {
50	            throw new IllegalArgumentException("The retention period of the window store "
51	                    + materialized.storeName() + " must be no smaller than its window size plus the grace period."
52	                    + " Got size=[" + windows.size() + "],"
53	                    + " grace=[" + windows.gracePeriodMs() + "],"
54	                    + " retention=[" + retentionPeriod + "]");
55	        }
56	    }
