58	    @Override
59	    public StoreBuilder<?> builder() {
60	        final WindowBytesStoreSupplier supplier =
61	            materialized.storeSupplier() == null
62	                ? dslStoreSuppliers().windowStore(new DslWindowParams(
63	                    materialized.storeName(),
64	                    Duration.ofMillis(retentionPeriod),
65	                    Duration.ofMillis(windows.size()),
66	                    false,
67	                    emitStrategy,
68	                    false,
69	                    dslStoreFormat()
70	                ))
71	                : (WindowBytesStoreSupplier) materialized.storeSupplier();
72	
73	        final StoreBuilder<?>  builder;
74	        if (supplier instanceof HeadersBytesStoreSupplier) {
75	            builder = Stores.timestampedWindowStoreWithHeadersBuilder(
