81	            builder = Stores.timestampedWindowStoreBuilder(
82	                supplier,
83	                materialized.keySerde(),
84	                materialized.valueSerde()
85	            );
86	        }
87	
88	        if (materialized.loggingEnabled()) {
89	            builder.withLoggingEnabled(materialized.logConfig());
90	        } else {
91	            builder.withLoggingDisabled();
92	        }
93	
94	        if (materialized.cachingEnabled()) {
95	            builder.withCachingEnabled();
96	        }
